import { pgTable, uuid, timestamp, text, uniqueIndex } from "drizzle-orm/pg-core";

export const slots = pgTable("slots", {
  id: uuid("id").primaryKey().defaultRandom(),
  staffId: uuid("staff_id").notNull(),
  startsAt: timestamp("starts_at", { withTimezone: true }).notNull(),
});

export const bookings = pgTable(
  "bookings",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    slotId: uuid("slot_id").notNull().references(() => slots.id),
    email: text("email").notNull(),
  },
  // one booking per slot, enforced by the database, not by the app
  (t) => [uniqueIndex("bookings_slot_once").on(t.slotId)],
);

