import { createORPCClient } from "@orpc/client";
import { RPCLink } from "@orpc/client/fetch";
import type { contract } from "@avel/contract";

// the only way the web talks to the backend: typed from packages/contract
export const client = createORPCClient<typeof contract>(
  new RPCLink({ url: "/api/rpc", headers: () => ({ "x-avel-client": "web" }) }),
);

