export function Sheet({ open, onClose, children }: SheetProps) {
  // focus moves in, the page behind goes inert, Escape closes, focus comes back
  useSheet(ref, { open, onClose });
  return open ? <div role="dialog" aria-modal ref={ref}>{children}</div> : null;
}
